def create_creature_on_battlefield(game, player, card_name):
    """Create a creature in HAND (no card_def), move it to battlefield via
    ZONE_CHANGE so interceptors register exactly once."""
    card_def = LORWYN_CUSTOM_CARDS[card_name]
    creature = game.create_object(
        name=card_name,
        owner_id=player.id,
        zone=ZoneType.HAND,
        characteristics=card_def.characteristics,
        card_def=None,
    )
    creature.card_def = card_def
    game.emit(Event(
        type=EventType.ZONE_CHANGE,
        payload={
            'object_id': creature.id,
            'from_zone': f'hand_{player.id}',
            'to_zone': 'battlefield',
            'to_zone_type': ZoneType.BATTLEFIELD,
        },
    ))
    return creature


