if __name__ == "__main__":
    import traceback
    tests = [(k, v) for k, v in sorted(globals().items()) if k.startswith("test_")]
    passed, failed, errored = [], [], []
    for name, fn in tests:
        try:
            fn()
            passed.append(name)
        except AssertionError as e:
            failed.append((name, str(e)))
        except Exception as e:
            errored.append((name, f"{type(e).__name__}: {e}"))

    print(f"\n=== Interceptor verification: custom/lorwyn_custom ===")
    print(f"  passed:  {len(passed)}")
    print(f"  failed:  {len(failed)}")
    print(f"  errored: {len(errored)}")
    print(f"  skipped: {len(SKIPPED_CARDS)} (see SKIPPED_CARDS)")
    if failed:
        print("\n--- FAILURES (top 20) ---")
        for name, msg in failed[:20]:
            print(f"  {name}: {msg}")
    if errored:
        print("\n--- ERRORS (top 20) ---")
        for name, msg in errored[:20]:
            print(f"  {name}: {msg}")
    total = len(passed) + len(failed) + len(errored)
    if total:
        pct = 100 * len(passed) / total
        print(f"\npass rate: {pct:.1f}%")
    sys.exit(0 if not failed and not errored else 1)
